  <style>
    :root{font-family:"Hind Siliguri","DM Sans",sans-serif;color:#17152f;background:#f7f6fc;font-synthesis:none}*{box-sizing:border-box}body{margin:0}.wrap{width:min(1060px,calc(100% - 32px));margin:42px auto}.top{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:26px}.brand{font:700 18px "DM Sans",sans-serif}.brand small{display:block;font:500 11px "DM Sans",sans-serif;letter-spacing:1px;color:#77738d;margin-top:4px}.top a{color:#6741d9;text-decoration:none}.card{background:#fff;border:1px solid #e7e4f0;border-radius:14px;padding:25px;box-shadow:0 8px 24px #34236f0a}.intro h1{font-size:32px;margin:0 0 5px}.muted{color:#716f83}.notice{padding:14px 16px;border-radius:9px;background:#f0ecff;color:#403276;margin:20px 0}.login{max-width:440px;margin:70px auto}.login h1{margin:0 0 8px}.field{display:grid;gap:6px;margin:14px 0}.field input{font:inherit;padding:11px;border:1px solid #dcd8e8;border-radius:8px}.button{border:0;border-radius:8px;padding:11px 16px;background:#6741d9;color:white;font:600 14px inherit;cursor:pointer}.button:disabled{opacity:.6;cursor:wait}.button.secondary{background:#f0ecff;color:#49348a}.error{color:#a23145;min-height:1.5em}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin:18px 0}.stat strong{font:700 25px "DM Sans",sans-serif;display:block}.stat span{color:#706d82;font-size:14px}.toolbar{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:14px}.toolbar-actions{display:flex;align-items:center;gap:10px}.sort-control{font:inherit;border:1px solid #dcd8e8;border-radius:8px;padding:10px 12px;background:#fff;color:#39354f}.leads{display:grid;gap:12px}.lead{padding:18px;border:1px solid #ece9f3;border-radius:10px}.lead-head{display:flex;justify-content:space-between;gap:14px;align-items:flex-start}.lead h2{margin:0;font-size:18px}.lead p{white-space:pre-wrap;margin:12px 0;color:#49465f}.lead-meta{font-size:13px;color:#716f83}.lead-meta a{color:#6741d9}.lead select{font:inherit;border:1px solid #dcd8e8;border-radius:7px;padding:7px;background:white}.empty{text-align:center;padding:40px;color:#716f83}.hidden{display:none!important}#setup{white-space:pre-wrap}
    @media(max-width:620px){.wrap{margin:22px auto}.card{padding:18px}.top{align-items:flex-start}.stats{grid-template-columns:1fr}.toolbar{align-items:flex-start;flex-direction:column}.toolbar-actions{width:100%;flex-wrap:wrap}.sort-control{flex:1;min-width:190px}.lead-head{flex-direction:column}}
        .chat-admin{margin-top:20px}.chat-admin-grid{display:grid;grid-template-columns:minmax(190px,.72fr) minmax(0,1.5fr);gap:14px}.chat-conversations{display:grid;align-content:start;gap:8px;max-height:430px;overflow:auto}.conversation-button{text-align:left;border:1px solid #e7e4f0;border-radius:9px;padding:11px;background:#fff;color:#39354f;cursor:pointer}.conversation-button.active{border-color:#6741d9;background:#f4f1ff}.conversation-button strong,.conversation-button small{display:block}.conversation-button small{color:#716f83;margin-top:3px}.chat-thread{display:flex;flex-direction:column;min-height:360px;border:1px solid #ece9f3;border-radius:10px;overflow:hidden}.admin-visitor-details{padding:11px 14px;border-bottom:1px solid #ece9f3;background:#fff;color:#39354f;font-size:13px}.admin-visitor-details strong,.admin-visitor-details a{display:block;overflow-wrap:anywhere}.admin-visitor-details a{color:#6741d9;margin-top:3px}.admin-transcript{flex:1;min-height:260px;max-height:420px;display:flex;flex-direction:column;gap:9px;padding:14px;overflow:auto;background:#faf9fd}.admin-bubble{max-width:min(82%,520px);padding:10px 12px;border-radius:12px;background:#eeeaf9;color:#39354f;white-space:pre-wrap;overflow-wrap:anywhere}.admin-bubble.admin{align-self:flex-end;background:#6741d9;color:#fff;border-bottom-right-radius:3px}.admin-bubble.visitor{align-self:flex-start;border-bottom-left-radius:3px}.admin-bubble time{display:block;margin-top:5px;font-size:11px;opacity:.72}.admin-chat-form{display:flex;gap:8px;padding:10px;border-top:1px solid #ece9f3}.admin-chat-form textarea{flex:1;resize:vertical;min-height:44px;max-height:120px;padding:9px;border:1px solid #dcd8e8;border-radius:8px;font:inherit}.chat-status{min-height:1.5em;margin:8px 0 0}.chat-empty{padding:18px;text-align:center;color:#716f83}.admin-chat-title{margin:0 0 12px;font-size:22px}@media(max-width:620px){.chat-admin-grid{grid-template-columns:1fr}.chat-conversations{max-height:180px}.admin-transcript{min-height:240px;max-height:340px}.chat-thread{min-height:300px}.admin-chat-form{flex-direction:column}.admin-chat-form .button{align-self:flex-end}}
