<body>
  <main class="wrap">
    <header class="top"><a href="/" class="brand">Nur Muhammad<small>PRIVATE LEAD INBOX</small></a><a href="/">মূল ওয়েবসাইটে ফিরুন ↗</a></header>
    <section id="setup" class="notice hidden"></section>
    <section id="login" class="card login">
      <h1>Sign in</h1><p class="muted">অনুমোদিত অ্যাকাউন্ট দিয়ে ব্যক্তিগত inquiry দেখুন।</p>
      <button class="button" id="googleLogin" type="button">Google দিয়ে Sign in করুন</button>
      <p class="muted">Dashboard admin হিসেবে যুক্ত Google account ব্যবহার করুন।</p><p class="error" id="loginError" aria-live="polite"></p>
      <details><summary>ইমেইল ও পাসওয়ার্ড দিয়ে Sign in</summary><p class="muted">তথ্যগুলো নিচের ঘরে লিখে Sign in চাপুন। URL-এর শেষে ইমেইল/পাসওয়ার্ড লিখলে লগইন হবে না।</p><form id="loginForm"><label class="field">ইমেইল<input name="email" type="email" autocomplete="username" required></label><label class="field">পাসওয়ার্ড<input name="password" type="password" autocomplete="current-password" required></label><button class="button secondary" type="submit">Sign in</button></form></details>
    </section>
    <section id="inbox" class="hidden">
      <header class="intro"><h1>Contact inquiries</h1><p class="muted">ওয়েবসাইটের যোগাযোগ ফর্ম থেকে পাওয়া বার্তা।</p></header>
      <div class="stats"><article class="card stat"><strong id="totalCount">0</strong><span>মোট inquiry</span></article><article class="card stat"><strong id="newCount">0</strong><span>নতুন</span></article><article class="card stat"><strong id="activeCount">0</strong><span>যোগাযোগ চলছে</span></article></div>
      <div class="toolbar"><strong>সব inquiry</strong><div class="toolbar-actions"><label class="muted" for="leadSort">সাজান</label><select class="sort-control" id="leadSort" aria-label="ইনকোয়ারি সাজান"><option value="newest">নতুন আগে</option><option value="oldest">পুরোনো আগে</option><option value="name_asc">নাম: A–Z</option><option value="name_desc">নাম: Z–A</option><option value="status">স্ট্যাটাস</option></select><button class="button secondary" id="signOut" type="button">Sign out</button></div></div>
      <p class="error" id="inboxError" aria-live="polite"></p><div id="leadList" class="leads"></div>
      <section class="card chat-admin" aria-labelledby="chatAdminTitle"><h2 class="admin-chat-title" id="chatAdminTitle">ওয়েবসাইট Live chat</h2><p class="muted">Visitor-এর সঙ্গে সাইটের ভেতরেই মেসেজ আদান-প্রদান করুন। বার্তা কিছু সেকেন্ড পরপর refresh হবে।</p><p class="error chat-status" id="adminChatStatus" aria-live="polite"></p><div class="chat-admin-grid"><div class="chat-conversations" id="chatConversationList"><div class="chat-empty">কোনো conversation নেই।</div></div><div class="chat-thread"><div class="admin-visitor-details" id="adminChatVisitor">Visitor-এর তথ্য এখানে দেখাবে।</div><div class="admin-transcript" id="adminChatMessages" aria-live="polite"><div class="chat-empty">কথোপকথন খুলতে বাম পাশের তালিকা থেকে একটি conversation বেছে নিন।</div></div><form class="admin-chat-form" id="adminChatForm"><textarea id="adminChatReply" maxlength="2000" placeholder="আপনার reply লিখুন…” required></textarea><button class="button" type="submit" id="adminChatSend" disabled>Reply পাঠান</button></form></div></div></section>
    </section>
  </main>
  <script>window.SUPABASE_CONFIG = <?= $safeConfig ?: '{}' ?>;</script>
  <script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script>
  <script>
    (async()=>{
      const config=window.SUPABASE_CONFIG||{};
      const setup=document.getElementById('setup'),login=document.getElementById('login'),inbox=document.getElementById('inbox');
      const loginError=document.getElementById('loginError');
      const query=new URLSearchParams(location.search);
      if(query.has('email')||query.has('password')){history.replaceState(null,'',location.pathname+location.hash);loginError.textContent='URL-এ দেওয়া তথ্য দিয়ে লগইন হয় না। নিচের form-এ তথ্য লিখুন; নিরাপত্তার জন্য exposed password বদলে নিন.'}
      const oauthError=query.get('error_description');
      if(oauthError){history.replaceState(null,'',location.pathname+location.hash);loginError.textContent='Google sign-in ব্যর্থ হয়েছে। Supabase Auth-এর Google provider এবং callback URL যাচাই করুন.'}
      if(!config.url||!config.anonKey||!window.supabase){setup.classList.remove('hidden');setup.textContent='Supabase এখনও configure করা হয়নি। Project URL এবং publishable/anon key Vercel environment variables-এ যোগ করে redeploy করুন।';return}
      const client=window.supabase.createClient(config.url,config.anonKey);
      const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
      let activeChatId=null,activeChatDetails=null,chatRefreshTimer=null,chatLoading=false;
      async function loadLeads(){
        document.getElementById('inboxError').textContent='';
        const sort=document.getElementById('leadSort').value;
        const {column,ascending}=({newest:{column:'created_at',ascending:false},oldest:{column:'created_at',ascending:true},name_asc:{column:'name',ascending:true},name_desc:{column:'name',ascending:false},status:{column:'status',ascending:true}}[sort]||{column:'created_at',ascending:false});
        let query=client.from('website_leads').select('id,name,email,phone,message,status,created_at').order(column,{ascending});
        if(sort==='status')query=query.order('created_at',{ascending:false});
        const {data,error}=await query;
        if(error){document.getElementById('inboxError').textContent='ডেটা লোড করা যায়নি। আপনার dashboard access allowlist-এ আছে কি না যাচাই করুন.';return}
        document.getElementById('totalCount').textContent=data.length;
        document.getElementById('newCount').textContent=data.filter(lead=>lead.status==='new').length;
        document.getElementById('activeCount').textContent=data.filter(lead=>lead.status==='contacted').length;
        const list=document.getElementById('leadList');
        if(!data.length){list.innerHTML='<div class="card empty">এখনো কোনো inquiry আসেনি।</div>';return}
        list.innerHTML=data.map(lead=>{const date=new Date(lead.created_at).toLocaleString('bn-BD');const contact=[lead.email?`<a href="mailto:${esc(lead.email)}">${esc(lead.email)}</a>`:'',lead.phone?`<a href="tel:${esc(lead.phone)}">${esc(lead.phone)}</a>`:''].filter(Boolean).join(' · ');return `<article class="card lead"><div class="lead-head"><div><h2>${esc(lead.name)}</h2><div class="lead-meta">${contact||'যোগাযোগের তথ্য নেই'} · ${esc(date)}</div></div><select aria-label="Inquiry status" data-id="${esc(lead.id)}"><option value="new" ${lead.status==='new'?'selected':''}>নতুন</option><option value="contacted" ${lead.status==='contacted'?'selected':''}>যোগাযোগ করা হয়েছে</option><option value="closed" ${lead.status==='closed'?'selected':''}>বন্ধ</option></select></div><p>${esc(lead.message)}</p></article>`}).join('');
        list.querySelectorAll('select[data-id]').forEach(select=>select.addEventListener('change',async()=>{select.disabled=true;const {error}=await client.from('website_leads').update({status:select.value}).eq('id',select.dataset.id);select.disabled=false;if(error){document.getElementById('inboxError').textContent='Status update failed. Check dashboard access.';await loadLeads()}else await loadLeads()}));
      }
      function chatTime(value){return new Date(value).toLocaleString('bn-BD',{timeZone:'Asia/Dhaka',dateStyle:'short',timeStyle:'short'})}
      async function loadChatMessages(){const list=document.getElementById('adminChatMessages'),status=document.getElementById('adminChatStatus'),send=document.getElementById('adminChatSend'),visitor=document.getElementById('adminChatVisitor');send.disabled=!activeChatId;if(!activeChatId){visitor.textContent='Visitor-এর তথ্য এখানে দেখাবে।';list.innerHTML='<div class="chat-empty">কথোপকথন খুলতে বাম পাশের তালিকা থেকে একটি conversation বেছে নিন।</div>';return}const name=activeChatDetails?.visitor_name||'Visitor';const email=activeChatDetails?.visitor_email||'';visitor.innerHTML=`<strong>${esc(name)}</strong>${email?`<a href="mailto:${encodeURIComponent(email)}">${esc(email)}</a>`:'ইমেইল দেওয়া হয়নি'}`;const {data,error}=await client.from('site_chat_messages').select('id,sender,body,created_at').eq('conversation_id',activeChatId).order('created_at',{ascending:true}).limit(100);if(error){status.textContent='Chat history load হয়নি। Supabase-এ supabase/chat-visitor-identity.sql migration চালান।';return}status.textContent='';if(!data.length){list.innerHTML='<div class="chat-empty">এখনো কোনো message নেই।</div>';return}list.innerHTML=data.map(message=>`<div class="admin-bubble ${message.sender==='admin'?'admin':'visitor'}"><span>${esc(message.body)}</span><time>${message.sender==='admin'?'Nur':esc(name)} · ${esc(chatTime(message.created_at))}</time></div>`).join('');list.scrollTop=list.scrollHeight}
      async function refreshChat(){if(chatLoading)return;chatLoading=true;const status=document.getElementById('adminChatStatus');try{const {data,error}=await client.from('site_chat_conversations').select('id,visitor_name,visitor_email,created_at,last_message_at').order('last_message_at',{ascending:false}).limit(50);if(error){status.textContent='Chat database setup হয়নি। Supabase SQL Editor-এ supabase/chat-visitor-identity.sql চালান.';return}const list=document.getElementById('chatConversationList');if(!data.length){activeChatId=null;activeChatDetails=null;list.innerHTML='<div class="chat-empty">কোনো conversation নেই।</div>';await loadChatMessages();return}if(!data.some(item=>item.id===activeChatId))activeChatId=data[0].id;activeChatDetails=data.find(item=>item.id===activeChatId)||data[0];list.innerHTML=data.map(item=>`<button type="button" class="conversation-button ${item.id===activeChatId?'active':''}" data-chat-id="${esc(item.id)}"><strong>${esc(item.visitor_name||'Visitor')}</strong><small>${esc(item.visitor_email||'ইমেইল নেই')} · ${esc(chatTime(item.last_message_at))}</small></button>`).join('');list.querySelectorAll('[data-chat-id]').forEach(button=>button.addEventListener('click',async()=>{activeChatId=button.dataset.chatId;activeChatDetails=data.find(item=>item.id===activeChatId)||null;list.querySelectorAll('.conversation-button').forEach(item=>item.classList.toggle('active',item.dataset.chatId===activeChatId));await loadChatMessages()}));await loadChatMessages()}finally{chatLoading=false}}
      async function showSession(session){if(session){login.classList.add('hidden');inbox.classList.remove('hidden');await loadLeads();await refreshChat();if(!chatRefreshTimer)chatRefreshTimer=setInterval(refreshChat,3500)}else{if(chatRefreshTimer){clearInterval(chatRefreshTimer);chatRefreshTimer=null}inbox.classList.add('hidden');login.classList.remove('hidden')}}
      // Bind sign-in controls before session restoration so an auth read failure
      // cannot leave the visible buttons inert.
      const googleButton=document.getElementById('googleLogin');
      googleButton.addEventListener('click',async()=>{const errorNode=document.getElementById('loginError');errorNode.textContent='Google sign-in শুরু হচ্ছে…';googleButton.disabled=true;try{const {error}=await client.auth.signInWithOAuth({provider:'google',options:{redirectTo:`${location.origin}/dashboard`}});if(error)throw error}catch(error){errorNode.textContent=`Google sign-in শুরু হয়নি: ${error?.message||'Supabase Google provider যাচাই করুন.'}`;googleButton.disabled=false}});
      document.getElementById('loginForm').addEventListener('submit',async event=>{event.preventDefault();const form=new FormData(event.currentTarget);const errorNode=document.getElementById('loginError');errorNode.textContent='Sign-in হচ্ছে…';const button=event.currentTarget.querySelector('button');button.disabled=true;try{const {error}=await client.auth.signInWithPassword({email:form.get('email'),password:form.get('password')});if(error)throw error}catch(error){const message=error?.message||'';errorNode.textContent=/invalid login credentials/i.test(message)?'ইমেইল/পাসওয়ার্ড মেলেনি। Google account হলে Google দিয়ে Sign in করুন; password login-এর জন্য Supabase Auth-এ password থাকতে হবে.':/email not confirmed/i.test(message)?'এই email confirm হয়নি। Supabase Auth email confirmation সম্পন্ন করুন.':`Sign-in ব্যর্থ: ${message||'Supabase Auth account যাচাই করুন.'}`;button.disabled=false}});
      client.auth.onAuthStateChange((_event,nextSession)=>{setTimeout(()=>showSession(nextSession),0)});
      const sessionRequest=client.auth.getSession().catch(()=>({data:{session:null}}));
      const sessionResult=await Promise.race([sessionRequest,new Promise(resolve=>setTimeout(()=>resolve({data:{session:null}}),5000))]);
      await showSession(sessionResult.data?.session||null);
      document.getElementById('leadSort').addEventListener('change',loadLeads);
      document.getElementById('adminChatForm').addEventListener('submit',async event=>{event.preventDefault();if(!activeChatId)return;const input=document.getElementById('adminChatReply'),button=document.getElementById('adminChatSend'),status=document.getElementById('adminChatStatus'),message=input.value.trim();if(!message)return;button.disabled=true;status.textContent='পাঠানো হচ্ছে…';const {error}=await client.rpc('admin_send_site_chat_message',{p_conversation_id:activeChatId,p_message:message});button.disabled=false;if(error){status.textContent='Reply পাঠানো যায়নি। Dashboard admin access যাচাই করুন.';return}input.value='';status.textContent='';await loadChatMessages();await refreshChat()});
      document.getElementById('signOut').addEventListener('click',()=>client.auth.signOut());
    })();
  </script>
</body>
</html>
